                    if (g.__COOPT_PROFILE_TRANSVERSE === true) return true;
                    const qs = new URLSearchParams(window.location?.search || '');
                    const qv = String(qs.get('coopt_profile_transverse') ?? qs.get('profileTransverse') ?? '').trim().toLowerCase();
